@page "/dashboard"
@using sv_1a7ad58559c94850b8f1a41d502230b6.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h3>Dashboard — @WarehouseState.SelectedWarehouseName</h3>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @CountClass">@AlertService.LastLowStockCount</p>
                <p class="text-muted small">
                    Items below minimum level
                    <br />
                    <em>Refreshes every 10 seconds</em>
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Active Warehouse</h5>
                <dl class="mb-0">
                    <dt>ID</dt>
                    <dd>@WarehouseState.SelectedWarehouseId</dd>
                    <dt>Name</dt>
                    <dd>@WarehouseState.SelectedWarehouseName</dd>
                    <dt>Polling Status</dt>
                    <dd><span class="badge bg-success">Active</span></dd>
                </dl>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;

    private string CountClass => AlertService.LastLowStockCount switch
    {
        > 10 => "text-danger",
        > 5 => "text-warning",
        > 0 => "text-info",
        _ => "text-secondary"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch
            await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
            }
        }
        catch (OperationCanceledException) { }
    }

    private void HandleWarehouseChanged()
    {
        // Restart polling for new warehouse and fetch immediately
        InvokeAsync(async () =>
        {
            StartPolling();
            await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
            StateHasChanged();
        });
    }

    private void HandleAlertChanged() => InvokeAsync(StateHasChanged);

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
    }
}

